import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"21、【噬嗑】 震下離上","description":"溫公易說 - 21、【噬嗑】 震下離上","frontmatter":{"title":"21、【噬嗑】 震下離上","description":"溫公易說 - 21、【噬嗑】 震下離上"},"headers":[],"relativePath":"classics/wengong/022.md","filePath":"classics/wengong/022.md"}'),l={name:"classics/wengong/022.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_21、【噬嗑】-震下離上" tabindex="-1">21、【噬嗑】 震下離上 <a class="header-anchor" href="#_21、【噬嗑】-震下離上" aria-label="Permalink to “21、【噬嗑】 震下離上”">​</a></h1><h3 id="彖曰-頤中有物曰噬嗑-噬嗑而亨。剛柔分-動而明-雷電合而章。柔得中而上行-雖不當位-利用獄也。" tabindex="-1">彖曰：頤中有物曰噬嗑，噬嗑而亨。剛柔分，動而明，雷電合而章。柔得中而上行，雖不當位，利用獄也。 <a class="header-anchor" href="#彖曰-頤中有物曰噬嗑-噬嗑而亨。剛柔分-動而明-雷電合而章。柔得中而上行-雖不當位-利用獄也。" aria-label="Permalink to “彖曰：頤中有物曰噬嗑，噬嗑而亨。剛柔分，動而明，雷電合而章。柔得中而上行，雖不當位，利用獄也。”">​</a></h3><h3 id="象曰-雷電噬嗑-先王以明罰勑法。" tabindex="-1">象曰：雷電噬嗑，先王以明罰勑法。 <a class="header-anchor" href="#象曰-雷電噬嗑-先王以明罰勑法。" aria-label="Permalink to “象曰：雷電噬嗑，先王以明罰勑法。”">​</a></h3><p>明罰勑法，先王明罰，非以殘人，所以正法也。</p><h3 id="初九-屨校滅趾-無咎-象曰-屨校滅趾-不行也。" tabindex="-1">初九：屨校滅趾，無咎 象曰：屨校滅趾，不行也。 <a class="header-anchor" href="#初九-屨校滅趾-無咎-象曰-屨校滅趾-不行也。" aria-label="Permalink to “初九：屨校滅趾，無咎 象曰：屨校滅趾，不行也。”">​</a></h3><h3 id="六二-噬膚滅鼻-無咎-象曰-噬膚滅鼻-乘剛也。" tabindex="-1">六二：噬膚滅鼻，無咎 象曰：噬膚滅鼻，乘剛也。 <a class="header-anchor" href="#六二-噬膚滅鼻-無咎-象曰-噬膚滅鼻-乘剛也。" aria-label="Permalink to “六二：噬膚滅鼻，無咎 象曰：噬膚滅鼻，乘剛也。”">​</a></h3><h3 id="六三-噬臘肉-遇毒-小吝-無咎-象曰-遇毒-位不當也。" tabindex="-1">六三：噬臘肉，遇毒，小吝，無咎 象曰：遇毒，位不當也。 <a class="header-anchor" href="#六三-噬臘肉-遇毒-小吝-無咎-象曰-遇毒-位不當也。" aria-label="Permalink to “六三：噬臘肉，遇毒，小吝，無咎 象曰：遇毒，位不當也。”">​</a></h3><p>噬嗑，食也，故皆以食物明之。禽獸全乾者謂之臘，噬之至難者也。乾肉，噬膚而難於幹胏者也。</p><h3 id="九四-噬幹胏-得金矢-利艱貞-吉-象曰-利艱貞-吉-未光也。" tabindex="-1">九四：噬幹胏，得金矢，利艱貞，吉 象曰：利艱貞，吉，未光也。 <a class="header-anchor" href="#九四-噬幹胏-得金矢-利艱貞-吉-象曰-利艱貞-吉-未光也。" aria-label="Permalink to “九四：噬幹胏，得金矢，利艱貞，吉 象曰：利艱貞，吉，未光也。”">​</a></h3><h3 id="六五-噬乾肉-得黃金-貞厲-無咎-象曰-貞厲-無咎-得當也。" tabindex="-1">六五：噬乾肉，得黃金，貞厲，無咎 象曰：貞厲，無咎，得當也。 <a class="header-anchor" href="#六五-噬乾肉-得黃金-貞厲-無咎-象曰-貞厲-無咎-得當也。" aria-label="Permalink to “六五：噬乾肉，得黃金，貞厲，無咎 象曰：貞厲，無咎，得當也。”">​</a></h3><h3 id="上九-何校滅耳-兇-象曰-何校滅耳-聰不明也。" tabindex="-1">上九：何校滅耳，兇 象曰：何校滅耳，聰不明也。 <a class="header-anchor" href="#上九-何校滅耳-兇-象曰-何校滅耳-聰不明也。" aria-label="Permalink to “上九：何校滅耳，兇 象曰：何校滅耳，聰不明也。”">​</a></h3>',11)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
